[data-segmentation]:not(.show):not(.js-billboard-group-candidate):not(.js-home-multishowcase-candidate) {
  visibility: hidden;
}

[data-segmentation].show,
[data-segmentation].js-billboard-group-candidate,
[data-segmentation].js-home-multishowcase-candidate {
  visibility: visible;
}

.multi-showcase-stack {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.multi-showcase-stack > .js-home-multishowcase-candidate {
  grid-column: 1;
  grid-row: 1;
  margin-bottom: 0;
  min-width: 0;
}

.banner-leaderboard-wrapper {
    --leaderboard-aspect-ratio-mobile: 1080/130;
    --leaderboard-aspect-ratio-desktop: 1220/45;
    --max-height-mobile: 130px;
    --max-height-desktop: 45px;

    position: relative;
    overflow: hidden;
    width: 100%;
    aspect-ratio: var(--leaderboard-aspect-ratio-mobile);
    max-height: var(--max-height-mobile);
}
.banner-leaderboard-wrapper.header-sticky {
    position: sticky;
    top: 0;
    z-index: 23;
}

.leaderboard-skeleton {
    width: 100%;
    height: 100%;
    max-width: 1220px;
    margin: auto;
    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
    background-size: 200% 100%;
    opacity: 1;
    transition: opacity 0.3s ease-in-out;
    z-index: 1;
}

/* Container do conteúdo lazysizes */
.leaderboard-container {
    position: absolute;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
}

.banner-leaderboard-wrapper:has(.leaderboard-container.lazyloaded) .leaderboard-skeleton {
    opacity: 0;
    pointer-events: none;
}

.banner-leaderboard-wrapper.leaderboard-empty {
    aspect-ratio: unset;
    max-height: 0;
    min-height: 0;
    overflow: hidden;
}

@media (min-width: 520px) {
    .banner-leaderboard-wrapper {
        aspect-ratio: var(--leaderboard-aspect-ratio-desktop);
        max-height: var(--max-height-desktop);
        min-height: 40px;
    }

    .banner-leaderboard-wrapper:has(video) {
        min-height: initial;
    }
}

