        IMG_SRC: presentationModalConfig.content.imgSrc,
        IMG_ALT: presentationModalConfig.content.imgAlt,
        IMG_EXTRA_CLASS: presentationModalConfig.content.imgExtraClass,
        TITLE: presentationModalConfig.content.title,
        DESCRIPTION: presentationModalConfig.content.description || fidelityConfig.awarenessAlert,
        BTN_STYLE: presentationModalConfig.content.btnStyle
    });

    const resolveModalConfig = (presentationModalConfig, fidelityConfig) => ({
        STORAGE_KEY: presentationModalConfig.storageKey,
        ANALYTICS: {
            EVENT: presentationModalConfig.analytics.event,
            NAME: presentationModalConfig.analytics.name,
            MODAL_REF: presentationModalConfig.analytics.modalRef
        },
        IDS: {
            CONTAINER: presentationModalConfig.ids.container
        },
        LINKS: {
            MEMBER: presentationModalConfig.links.member || presentationModalConfig.links.default,
            DEFAULT: presentationModalConfig.links.default
        },
        RULES: resolveRules(presentationModalConfig),
        CONTENT: resolveContent(presentationModalConfig, fidelityConfig)
    });

    const isFidelityMember = (memberData) => {
        return !!memberData && Object.hasOwn(memberData, 'tier');
    };

    const resolveLinkByMembership = (config, isMember) => {
        return isMember ? config.LINKS.MEMBER : config.LINKS.DEFAULT;
    };

    const fidelityConfig = parseFidelityConfig();
    const presentationModalConfig = resolvePresentationModalConfig(fidelityConfig);

    if (!presentationModalConfig) return;

    const storeConfig = resolveModalConfig(presentationModalConfig, fidelityConfig);
    const CONFIG = {
        ...BASE_CONFIG,
        ...storeConfig
    };

    const { buildModalHTML, fetchBalance } = createAwarenessModal(CONFIG);

    const resolveIsMember = async (userId) => {
        if (!userId) return false;

        if (isFidelityMember(globalThis.blz?.beautybox)) {
            return true;
        }

        const balanceData = await fetchBalance();
        return isFidelityMember(balanceData);
    };

    const initAwarenessModal = async () => {
        const pathname = globalThis.location?.pathname || '';

        if (CONFIG.RULES.shouldSkipPath(pathname)) return;

        const isSeen = globalThis.localStorage.getItem(CONFIG.STORAGE_KEY) === 'true';
        const modalExists = globalThis.document.getElementById(CONFIG.IDS.CONTAINER);

        if (isSeen || modalExists) return;

        const userId = globalThis.blz?.me?.id;
        const isHomePage = globalThis.blz?.pageType === 'Home' || pathname === '/';
        const isNotAllowedPage = ['loucas_post'].includes(globalThis.blz?.pageType);

        if (isNotAllowedPage) return;

        if (CONFIG.RULES.hasLightbox && !userId && isHomePage) return;
        if (CONFIG.RULES.ensureAuthenticatedToShow && !userId) return;

        const isMember = await resolveIsMember(userId);

        if (CONFIG.RULES.ensureMemberToShow && !isMember) return;

        return buildModalHTML(resolveLinkByMembership(CONFIG, isMember));
    };

    if (document.readyState === 'complete') {
        initAwarenessModal();
    } else {
        globalThis.addEventListener('load', initAwarenessModal);
    }
})();

