  const lastVisitedSkus = globalThis?.localStorage?.getItem('LAST_VISITED_SKUS');
  const multiShowcases = document.querySelectorAll('.js-multi-showcase');
  const classesToCheck = ['lazyload', 'lazyloaded', 'lazyloading'];

  if (multiShowcases.length === 0) {
    return;
  }

  multiShowcases.forEach((multiShowcase) => {
    const segmentationStack = multiShowcase.closest('.js-home-multishowcase-stack');

    if (
      multiShowcase.classList.contains('js-home-multishowcase-candidate') &&
      segmentationStack &&
      !segmentationStack.classList.contains('is-resolved')
    ) {
      return;
    }

    const hasLazyClass = classesToCheck.some((className) =>
      multiShowcase.classList.contains(className)
    );

    if (!lastVisitedSkus && !hasLazyClass) {
      multiShowcase.classList.add('lazyload');
      return;
    }

    const componentUrl = multiShowcase.dataset.include;

    if (!componentUrl) {
      return;
    }

    const url = new URL(componentUrl, globalThis.location.origin);
    const previousLastVisitedSkus = url.searchParams.get('lastVisitedSkus');
    const isEqual = previousLastVisitedSkus === lastVisitedSkus;

    if (lastVisitedSkus && !isEqual) {
      url.searchParams.set('lastVisitedSkus', lastVisitedSkus);
      multiShowcase.dataset.include = `${url.href}`;
      multiShowcase.classList.remove('lazyloaded', 'lazyloading');
      multiShowcase.classList.add('lazyload');
    }
  });
}

